const icon=name=>`<svg class="icon" aria-hidden="true" focusable="false"><use href="icons.svg#${name}"></use></svg>`;
const $=s=>document.querySelector(s);
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let notes=read('muguang-notes',[]);if(!Array.isArray(notes))notes=[];
let progress=read('refinetaste-course-v2',{});if(typeof progress!=='object'||Array.isArray(progress))progress={};
let course=null,current=0,chapter=0,selected=null,sessionAnswers={},screen='map',reviewController=null,reviewGeneration=0;
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function updateCount(){$('#note-count').textContent=notes.length}updateCount();
function checkpoint(){return progress[current]||{}}
function saveProgress(patch){progress[current]={...checkpoint(),...patch};const ok=persist('refinetaste-course-v2',progress);if(!ok&&$('#draft-storage'))$('#draft-storage').textContent='浏览器无法保存，离开前请复制或导出';return ok}
function focusTitle(){$('#training').scrollTop=0;$('#exercise-title')?.focus({preventScroll:true})}
function stopReview(){reviewGeneration++;reviewController?.abort();reviewController=null}
function transition(update){stopReview();return window.RefineMotion.swap($('#exercise'),()=>{update();focusTitle()})}
async function showMap(){
 stopReview();screen='map';$('#exit').innerHTML=icon('arrow-left')+' 返回首页';$('#exercise-progress').textContent='三阶课程 · 24 个练习';
 if(!course){$('#exercise').innerHTML='<div class="course-loading" role="status">正在打开课程…</div>';try{const r=await fetch('course.json');if(!r.ok)throw Error();course=await r.json()}catch{$('#exercise').innerHTML='<div class="empty"><h2 id="exercise-title">课程暂时没有打开</h2><p>请检查网络，再试一次。</p><button id="course-retry" class="primary">重新加载</button></div>';$('#course-retry').onclick=showMap;return}}
 $('#exercise').innerHTML=`<div class="course-map"><div class="exercise-heading"><span class="section-kicker">循序练习，逐渐形成自己的判断</span><h2 id="exercise-title" tabindex="-1">从看见，到说清，<br>再到判断。</h2><p>每阶 8 题，可独立练习。先比较，再表达，最后练习取舍。<br>12 道比较题 + 12 道开放题；思路和点评可以留作自己的设计笔记。</p></div><div class="course-chapters">${course.chapters.map((ch,i)=>{const qs=course.questions.filter(q=>q.chapter===i),done=qs.filter(q=>progress[q.id]?.done).length;return `<article class="course-chapter"><div class="chapter-number">${String(i+1).padStart(2,'0')}</div><div class="chapter-copy"><span class="section-kicker">${ch.level} · ${ch.minutes}</span><h3>${ch.title}</h3><p>${ch.subtitle}</p><small>练习目标：${ch.objective}</small><details><summary>看看这阶练什么 ${icon('nav-arrow-down')}</summary><ol>${qs.map(q=>`<li>${esc(q.title)} <span>${q.kind==='open'?q.format:'比较判断'}</span></li>`).join('')}</ol></details></div><div class="chapter-action"><span>${done?`已练 ${done} / 8 题`:'8 个练习'}</span><button class="${i===0?'primary':'secondary'}" data-chapter="${i}">${done?'再练这一阶':'开始这一阶'} ${icon('arrow-up-right')}</button></div></article>`}).join('')}</div><p class="course-footnote">原创案例练习，结合 GOV.UK、W3C 与伦敦地铁图的参考资料。经典案例附原始来源，练习画面均为原创示意。进度保留在当前浏览器。</p></div>`;
 document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>transition(()=>begin(+b.dataset.chapter)));focusTitle();
}
function begin(index){chapter=index;current=index*8;selected=null;sessionAnswers={};screen='lesson';window.RefineMetrics?.start(current);render()}
document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{$('#training').showModal();showMap()});
$('#exit').onclick=()=>{if(screen==='map'){stopReview();window.RefineMotion.closeDialog($('#training'))}else transition(showMap)};
$('#training').addEventListener('close',stopReview);
function sources(q){return q.sources?.length?`<div class="case-source">参考阅读：${q.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('arrow-up-right')}</a>`).join('')}<span>练习画面为原创示意，并非原站截图或原作复刻。</span></div>`:''}
function specimen(v){
 const cls=esc(v.kind),lines=v.lines.map(esc);
 let content=lines.map(t=>`<p>${t}</p>`).join('');
 if(v.kind.startsWith('menu'))content=lines.map(t=>`<div class="menu-row">${t.split('｜').map((x,i)=>`<span class="menu-part-${i}">${x}</span>`).join('')}</div>`).join('');
 if(v.kind.startsWith('status'))content=lines.map(t=>{const [name,status]=t.split('｜');return `<p class="status-row"><span>${name}</span><span class="status-marker ${status.includes('失败')||status==='红'?'failed':''}">${v.kind.includes('color-only')?'●':status}</span></p>`}).join('');
 if(v.kind.startsWith('chart'))content=`<div class="mini-chart ${v.kind.includes('truncated')?'axis-cut':''}"><div class="bar bar-a"><span>82</span></div><div class="bar bar-b"><span>84</span></div></div><div class="chart-key">活动 A　/　活动 B</div><p>${lines[2]}</p>`;
 return `<div class="specimen ${cls}"><div class="specimen-tag">${esc(v.tag)}</div><strong class="specimen-title">${esc(v.title)}</strong><div class="specimen-content">${content}</div></div>`
}
function render(){
 screen='lesson';const q=course.questions[current],ch=course.chapters[chapter];selected=sessionAnswers[current]??null;
 $('#exit').innerHTML=icon('arrow-left')+' 课程目录';$('#exercise-progress').textContent=`${ch.level} · ${current%8+1} / 8 · ${q.kind==='open'?q.format:'比较判断'}`;
 $('#exercise').innerHTML=`<div class="exercise-heading"><span class="section-kicker">${ch.title} / ${q.principle}</span><h2 id="exercise-title" tabindex="-1">${esc(q.title)}</h2><p>${esc(q.brief)}</p></div>${q.kind==='choice'?`<div class="options">${q.labels.map((label,i)=>`<button class="option" data-option="${i}" aria-label="选项 ${i?'B':'A'}：${esc(label)}">${q.visuals?.length?specimen(q.visuals[i]):sample(q,i)}<div class="option-label"><span class="letter">${i?'B':'A'}</span>${esc(label)}</div></button>`).join('')}</div>`:`<div class="open-case ${q.visuals.length>1?'case-pair':''}">${q.visuals.map(specimen).join('')}</div>`}${sources(q)}<div id="feedback-slot" aria-live="polite"></div>`;
 if(q.kind==='choice')document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>answer(+b.dataset.option));else renderOpen(q);focusTitle();
}
function recordAnswer(choice){if(Object.hasOwn(sessionAnswers,current))return;sessionAnswers[current]=choice;window.RefineMetrics?.send('answer',{q:current,choice});saveProgress({done:true,choice})}
function nextButton(){return `<button class="primary" id="next">${current%8===7?'查看本阶回顾':'下一练'} <span>${icon('arrow-right')}</span></button>`}
function bindNext(){$('#next').onclick=()=>transition(()=>{if(current%8===7)result();else{current++;selected=null;render()}})}
function answer(i){
 if(selected!==null)return;selected=i;recordAnswer(i);const q=course.questions[current];$('.options').classList.add('answered');
 document.querySelectorAll('[data-option]').forEach(b=>{b.disabled=true;b.classList.toggle('selected',+b.dataset.option===i);b.classList.toggle('correct',+b.dataset.option===q.correct)});
 $('#feedback-slot').innerHTML=`<div class="feedback"><h3>${i===q.correct?'你的判断有依据。':'换个角度，再观察一次。'}</h3><p>${esc(q.why)}</p><p><b>${esc(q.rule)}</b></p><div class="reflection"><label for="reflection">用自己的话，留下一条改进建议（选填）</label><textarea id="reflection" maxlength="2000" placeholder="我看到了什么？它影响了谁？我会怎样改？"></textarea><div class="save-row"><button class="secondary" id="save-note">记下这个发现 ${icon('plus')}</button><span class="save-status" role="status"></span></div></div><div class="feedback-actions"><span class="section-kicker">${esc(q.principle)}</span>${nextButton()}</div></div>`;
 $('#reflection').value=checkpoint().draft||'';$('#reflection').oninput=()=>saveProgress({draft:$('#reflection').value});$('#save-note').onclick=()=>saveNote(q,$('#reflection').value,$('.save-status'));bindNext();
}
function renderOpen(q){
 const saved=checkpoint();$('#feedback-slot').innerHTML=`<div class="open-workspace"><div class="open-prompt"><h3>用你的话，提出一个方案。</h3><p>${esc(q.prompt)}</p><div class="thinking-lenses">${q.rubric.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><form id="open-form"><label for="open-answer">你的判断与理由</label><textarea id="open-answer" minlength="30" maxlength="2000" required placeholder="我的目标是……我观察到……所以建议……这个方案的代价是……我会用……验证。"></textarea><div class="writing-meta"><span id="draft-storage">30—2000 字 · 草稿自动留在本机</span><span id="word-count"></span></div><p class="ai-disclosure">点击点评时，本题与你写下的思路将发给模型服务。请勿填写个人或业务机密。点评供讨论，不作为标准答案。</p><div class="open-actions"><button class="primary" type="submit" id="review-submit">请设计教练点评 ${icon('arrow-up-right')}</button><button class="secondary" type="button" id="self-review">先自行复盘</button></div><p id="review-status" role="status"></p></form><div id="model-review" aria-live="polite"></div><details class="reference"><summary>${icon('nav-arrow-right')}看看一种参考思路</summary><p>${esc(q.reference)}</p><small>这是一种可能的思路。不同方案可以成立，关键在于目标、依据与约束。</small></details><div class="open-bottom"><button class="secondary" id="save-open-note">保存思路与点评 ${icon('plus')}</button><span class="save-status" role="status"></span><div id="open-next" hidden>${nextButton()}</div></div></div>`;
 const input=$('#open-answer');input.value=saved.draft||'';const count=()=>{$('#word-count').textContent=input.value.trim().length+' 字'};count();
 input.oninput=()=>{saveProgress({draft:input.value});count();if($('#model-review').textContent)$('#review-status').textContent='思路已修改，现有点评对应上一稿。可以重新提交。'};
 $('#open-form').onsubmit=e=>{e.preventDefault();requestReview(q)};
 $('#self-review').onclick=()=>{if(!validateWriting())return;recordAnswer(-1);$('#review-status').textContent='已记录本次表达。可对照参考思路复盘，也可以稍后请教练点评。';$('#open-next').hidden=false};
 $('#save-open-note').onclick=()=>saveNote(q,input.value,$('.save-status'),checkpoint().reviewedDraft===input.value.trim()?checkpoint().feedback:null);
 if(saved.feedback&&saved.reviewedDraft===input.value)showFeedback(saved.feedback,saved.modelLabel);
 bindNext();
}
function validateWriting(){const text=$('#open-answer').value.trim();if(text.length<30||text.length>2000){$('#review-status').textContent='先写下 30—2000 字的具体思路，再继续。';$('#open-answer').focus();return false}return true}
async function requestReview(q){
 if(!validateWriting()||reviewController)return;const text=$('#open-answer').value.trim();saveProgress({draft:text});recordAnswer(-1);$('#open-next').hidden=false;
 const generation=++reviewGeneration,questionId=current;reviewController=new AbortController();const controller=reviewController;const timer=setTimeout(()=>controller.abort(),48000);$('#review-submit').disabled=true;$('#review-submit').textContent='教练正在读你的思路…';$('#review-status').textContent='正在结合题目和你的表达生成点评，可以稍后继续或返回目录。';$('#model-review').setAttribute('aria-busy','true');
 try{const r=await fetch('api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),q:questionId,answer:text}),signal:controller.signal});const data=await r.json();if(generation!==reviewGeneration||current!==questionId)return;if(!r.ok)throw Error(data.error||'点评暂时未完成，请稍后再试。');saveProgress({feedback:data.feedback,reviewedDraft:text,modelLabel:data.modelLabel});showFeedback(data.feedback,data.modelLabel);$('#review-status').textContent=$('#open-answer').value.trim()===text?'点评已完成。你可以修改思路再提交，也可以保存后继续。':'点评对应刚才提交的一稿；你已修改内容，可以再次提交。'}catch(error){if(generation!==reviewGeneration)return;$('#review-status').textContent=error.name==='AbortError'?'这次点评等待较久，请重试；你的草稿已留在本机。':error.message==='Failed to fetch'?'网络暂时无法连接，请重试；你的草稿已留在本机。':error.message}finally{clearTimeout(timer);if(generation===reviewGeneration){reviewController=null;$('#review-submit').disabled=false;$('#review-submit').innerHTML='再次请教练点评 '+icon('arrow-up-right');$('#model-review').removeAttribute('aria-busy')}}
}
function showFeedback(f,label='设计教练'){$('#model-review').innerHTML=`<section class="model-feedback"><div class="review-heading"><span class="section-kicker">${esc(label)} · 模型生成</span><h3>把思路，再往前推一步。</h3></div><div class="review-columns"><div><h4>已经站得住的部分</h4>${f.strengths.map(t=>`<p>${esc(t)}</p>`).join('')}</div><div><h4>还可以补上的部分</h4>${f.gaps.map(t=>`<p>${esc(t)}</p>`).join('')}</div></div><div class="review-suggestion"><h4>下一版可以这样试</h4><p>${esc(f.suggestion)}</p></div><details><summary>${icon('nav-arrow-right')}从四个角度检查这次表达</summary><dl>${f.dimensions.map(d=>`<div><dt>${esc(d.name)}</dt><dd>${esc(d.evidence)}</dd></div>`).join('')}</dl></details><p class="review-question">再想一步：${esc(f.question)}</p><small>模型可能遗漏情境；你可以提出不同判断，并说明理由。</small></section>`}
function saveNote(q,text,status,feedback){text=text.trim();if(!text){status.textContent='先写下一句自己的观察。';return}const review=feedback?'\n\n教练点评：\n'+[...feedback.strengths,...feedback.gaps,feedback.suggestion,feedback.question].join('\n'):'';notes.push({topic:q.principle,text:text+review,date:new Date().toLocaleDateString('zh-CN')});const ok=persist('muguang-notes',notes);updateCount();window.RefineMetrics?.send('note_saved');status.textContent=ok?'已保存到我的笔记。':'当前浏览器无法保存，请在关闭前导出笔记。'}
function result(){screen='result';window.RefineMetrics?.send('complete');const qs=course.questions.slice(chapter*8,chapter*8+8),choices=qs.filter(q=>q.kind==='choice'),correct=choices.filter(q=>sessionAnswers[q.id]===q.correct).length,opens=qs.filter(q=>q.kind==='open'),review=choices.filter(q=>sessionAnswers[q.id]!==q.correct);$('#exercise-progress').textContent='本阶回顾';$('#exercise').innerHTML=`<div class="result"><span class="section-kicker">${course.chapters[chapter].level} · ${course.chapters[chapter].title}</span><h2 id="exercise-title" tabindex="-1">让每个判断，<br>多一点自己的依据。</h2><div class="result-count">${correct}<small> / ${choices.length} 个比较判断</small></div><p>你还完成了 ${opens.length} 次开放表达。<br>开放题不判对错；比较题也只是本次情境下的判断，不是审美能力评分。</p>${review.length?`<p>值得再观察：${review.map(q=>esc(q.principle)).join('、')}。</p>`:''}<p>${esc(course.chapters[chapter].objective)}</p><div class="result-actions">${chapter<2?`<button class="primary" id="next-chapter">进入${course.chapters[chapter+1].level} ${icon('arrow-up-right')}</button>`:''}<button class="secondary" id="result-map">回到课程目录</button><button class="secondary" id="result-notes">查看我的笔记</button></div></div>`;if($('#next-chapter'))$('#next-chapter').onclick=()=>transition(()=>begin(chapter+1));$('#result-map').onclick=()=>transition(showMap);$('#result-notes').onclick=openNotes;focusTitle()}
function sample(q,i){if(q.type==='card')return `<div class="sample-card ${i===q.correct?'good':q.bad}"><div class="studio">LINJIAN DESIGN STUDIO</div><div><div class="name">陈默</div><div class="position">品牌设计师</div></div><div class="contact">hello@linjian.studio<br>138 0000 2026</div></div>`;if(q.type==='resource'||q.type==='offer'){const good=i===q.correct;const offer=q.type==='offer';return `<div class="resource-demo"><div class="app-bar"><b>生活灵感</b><span>附近　收藏</span></div><div class="resource-banner ${good?'':'loud'}"><strong>${offer?(good?'新客，来杯好咖啡。':'免费喝咖啡！'):(good?'周末，走慢一点。':'周末必去！立即出发！')}</strong><p>${offer?(good?'领 10 元咖啡券 · 满 30 元可用':'超值福利！限时抢！'):(good?'发现附近的 3 条散步路线':'发现宝藏路线！错过再等一年！')}</p><span>${offer?'去领券':'探索散步路线'} ${icon('arrow-right')}</span></div><div class="app-placeholder"><i></i><i></i><i></i></div></div>`}if(q.type==='path')return `<div class="path-sample"><div><small>用户看见</small>附近免费展览 ${icon('arrow-right')}</div><span>${icon('arrow-down')}</span><div><small>点击后抵达</small>${i===1?'附近免费展览列表 · 默认按距离排序':'品牌首页 · 商城 / 动态 / 会员 / 更多'}</div></div>`;return `<div class="path-sample"><div><small>给设计同事的反馈</small>${esc(q.labels[i])}</div><div><small>下一步</small>${i===1?'选出主利益，调整字号，再放回页面检验。':'设计师需要继续追问：「具体指哪里？」'}</div></div>`}
function openNotes(){$('#notes-list').innerHTML=notes.length?notes.map(n=>`<article class="note-item"><small>${esc(n.date)} · ${esc(n.topic)}</small><p>${esc(n.text)}</p></article>`).join(''):'<div class="empty">还没有留下观察。<br>完成一道练习，写下你的第一条改进建议。</div>';$('#export-notes').disabled=!notes.length;$('#notebook').showModal()}$('#notes-open').onclick=openNotes;$('#notebook-in').onclick=openNotes;$('#notes-close').onclick=()=>window.RefineMotion.closeDialog($('#notebook'));$('#export-notes').onclick=()=>{const text='设计积累 · 我的设计观察\n\n'+notes.map(n=>`${n.date} | ${n.topic}\n${n.text}`).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='设计积累-我的设计观察.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
